/*selectMasterWmGrTrGrCreList*/ SELECT A.STATUS, A.BUYER_NAME, A.PO_CREATE_DATE, A.RD_DATE, A.PO_CNT, A.DELY_TO_LOCATION, DECODE(A.ADD_USER_TEL,' ',A.ADD_USER_NAME,A.ADD_USER_NAME||'(' ||ADD_USER_TEL||')') AS ADD_USER_NAME, A.ADD_USER_NAME AS ADD_USER_NAME_ORG, A.ADD_USER_TEL, DECODE(A.AGENT_TEL_NO,' ' ,A.AGENT_NAME,A.AGENT_NAME||'('||AGENT_TEL_NO||')') AS AGENT_NAME, A.AGENT_NAME AS AGENT_NAME_ORG, A.AGENT_TEL_NO, A.GR_DATE_RE, A.PO_NO, A.LEGACY_PO_NO, A.INV_NO, A.ITEM_AMT, A.DOC_TEXT, A.DOC_TYPE, A.AGENT, A.BUYER, A.PRE_GR_FLAG, CASE WHEN (sysdate+7)-next_day(sysdate,1)+1 = 6 THEN sysdate+3 WHEN (sysdate+7)-next_day(sysdate,1)+1 = 7 THEN sysdate+2 ELSE SYSDATE+1 END AS SCHEDULED_DATE, NVL(B.CAR_ID,'') AS CAR_ID, NVL(B.CAR_NO,'') AS CAR_NO, NVL(B.CAR_PERSON_NAME,'') AS CAR_PERSON_NAME, NVL(B.CAR_PERSON_TEL,'') AS CAR_PERSON_TEL, 1 BOX_QTY, A.PO_REMARK, A.DELAY_REMARK, A.SCM_REMARK AS SCM_REMARK, A.CENTER_SCHD_DATE AS CENTER_SCHD_DATE, A.DELY_BUNDLE_FLAG, (SELECT TEXT7 FROM ICOMCOD1 WHERE TYPE='W001' AND FLAG='Y' AND TEXT4='B' AND TEXT1=A.DEPT_WAREHOUSE_CODE) AS DEPT_WAREHOUSE, (SELECT TEXT7 FROM ICOMCOD1 WHERE TYPE='W001' AND FLAG='Y' AND TEXT4='B' AND TEXT1=A.DEST_WAREHOUSE_CODE) AS DEST_WAREHOUSE, A.HUB_YN, DECODE((SELECT COUNT(*) FROM HUBIVDT WHERE BUYER = A.BUYER AND AGENT = A.AGENT AND PO_NO = A.PO_NO AND S_INV_NO = A.INV_NO), 0, 'Y', (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM HUBIVDT WHERE BUYER = A.BUYER AND AGENT = A.AGENT AND PO_NO = A.PO_NO AND S_INV_NO = A.INV_NO AND HUB_IV_DATE IS NOT NULL)) AS HUB_IV_YN FROM ( SELECT '발주' AS STATUS, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER)) AS BUYER_NAME, MAX(POHD.PO_CREATE_DATE) AS PO_CREATE_DATE, MAX(PODT.RD_DATE) AS RD_DATE, COUNT(PODT.PO_SEQ) AS PO_CNT, MAX(POHD.DELY_TO_LOCATION) AS DELY_TO_LOCATION, MAX(PRDT.ADD_USER_NAME) AS ADD_USER_NAME, MAX(PRDT.ADD_USER_TEL) AS ADD_USER_TEL, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_NAME, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_TEL_NO, '' AS GR_DATE_RE, PODT.PO_NO AS PO_NO, MAX(PODT.LEGACY_PO_NO) AS LEGACY_PO_NO, '' AS INV_NO, SUM(PODT.ITEM_AMT) AS ITEM_AMT, MAX(DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반')) AS DOC_TEXT, MAX(POHD.DOC_TYPE) AS DOC_TYPE, MAX(POHD.AGENT) AS AGENT, PODT.BUYER AS BUYER, MAX((SELECT PRE_GR_FLAG FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D')) AS PRE_GR_FLAG, MAX(POHD.PO_REMARK) AS PO_REMARK, PODT.DELAY_REMARK, MAX(PODT.SCM_REMARK) AS SCM_REMARK, MAX(TO_CHAR(TO_DATE(PODT.RD_DATE,'YYYY/MM/DD')-2,'YYYYMMDD')) AS CENTER_SCHD_DATE, ( SELECT NVL(MAX(A.DELY_BUNDLE_FLAG),'N') FROM ICOMPRDT A, ICOMPODT B WHERE A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.STATUS != 'D' AND B.STATUS != 'D' AND B.BUYER = PODT.BUYER AND B.PO_NO = PODT.PO_NO AND A.DELY_BUNDLE_FLAG = 'Y' ) AS DELY_BUNDLE_FLAG, MAX((SELECT DECODE(DELY_TO_CENTER, #{st_warehouse_code}, '', DELY_TO_CENTER) FROM SUPLINFO2 WHERE SUPPLIER = POHD.AGENT)) AS DEPT_WAREHOUSE_CODE, '' AS DEST_WAREHOUSE_CODE, 'N' AS HUB_YN FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.ITEM_QTY > PODT.IV_QTY AND PODT.COMPLETE_MARK = 'N' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND 1=1
AND 1=0
AND PODT.RD_DATE BETWEEN #{st_from_date} AND TO_CHAR(TO_DATE(#{st_to_date},'YYYYMMDD') + 2,'YYYYMMDD')
AND PODT.BUYER IN
#{st_buyer_code}
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND ( PODT.PO_NO IN
#{item}
OR PODT.LEGACY_PO_NO IN
#{item}
)
AND POHD.AGENT IN
#{st_agent_code}
AND PODT.PO_NO = #{st_iv_no}
AND PODT.PO_NO IN
#{st_iv_no_barcode}
AND POHD.DOC_TYPE = #{st_doc_type}
GROUP BY PODT.BUYER,PODT.PO_NO,PODT.DELAY_REMARK
UNION ALL
SELECT X.STATUS, X.BUYER_NAME, X.PO_CREATE_DATE, X.RD_DATE, X.PO_CNT, X.DELY_TO_LOCATION, X.ADD_USER_NAME, X.ADD_USER_TEL, X.AGENT_NAME, X.AGENT_TEL_NO, X.GR_DATE_RE, X.PO_NO, X.LEGACY_PO_NO, X.INV_NO, X.ITEM_AMT, X.DOC_TEXT, X.DOC_TYPE, X.AGENT, X.BUYER, X.PRE_GR_FLAG, X.PO_REMARK, X.DELAY_REMARK, X.SCM_REMARK, X.CENTER_SCHD_DATE, X.DELY_BUNDLE_FLAG, X.DEPT_WAREHOUSE_CODE, X.DEST_WAREHOUSE_CODE, X.HUB_YN FROM ( SELECT DECODE(MAX(PODT.ITEM_QTY),MAX(IVDT.INV_QTY),'입고예정','분할입고예정') AS STATUS, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER)) AS BUYER_NAME, MAX(POHD.PO_CREATE_DATE) AS PO_CREATE_DATE, MAX(PODT.RD_DATE) AS RD_DATE, COUNT(PODT.PO_SEQ) AS PO_CNT, MAX(POHD.DELY_TO_LOCATION) AS DELY_TO_LOCATION, MAX(PRDT.ADD_USER_NAME) AS ADD_USER_NAME, MAX(PRDT.ADD_USER_TEL) AS ADD_USER_TEL, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_NAME, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_TEL_NO, MAX(IVDT.INVOICE_DATE) AS GR_DATE_RE, PODT.PO_NO AS PO_NO, MAX(PODT.LEGACY_PO_NO) AS LEGACY_PO_NO, IVDT.INV_NO AS INV_NO, SUM(PODT.ITEM_AMT) AS ITEM_AMT, MAX(DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반')) AS DOC_TEXT, MAX(POHD.DOC_TYPE) AS DOC_TYPE, MAX(POHD.AGENT) AS AGENT, PODT.BUYER AS BUYER, MAX((SELECT PRE_GR_FLAG FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D')) AS PRE_GR_FLAG, MAX(POHD.PO_REMARK) AS PO_REMARK, PODT.DELAY_REMARK, MAX(PODT.SCM_REMARK) AS SCM_REMARK, MAX(TO_CHAR(TO_DATE(PODT.RD_DATE,'YYYY/MM/DD')-2,'YYYYMMDD')) AS CENTER_SCHD_DATE, ( SELECT NVL(MAX(A.DELY_BUNDLE_FLAG),'N') FROM ICOMPRDT A, ICOMPODT B WHERE A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.STATUS != 'D' AND B.STATUS != 'D' AND B.BUYER = PODT.BUYER AND B.PO_NO = PODT.PO_NO AND A.DELY_BUNDLE_FLAG = 'Y' ) AS DELY_BUNDLE_FLAG, MAX((SELECT DECODE(DELY_TO_CENTER, #{st_warehouse_code}, '', DELY_TO_CENTER) FROM SUPLINFO2 WHERE SUPPLIER = POHD.AGENT)) AS DEPT_WAREHOUSE_CODE, '' AS DEST_WAREHOUSE_CODE, 'N' AS HUB_YN FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMIVDT IVDT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.WMS_GR_QTY = 0 AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND PODT.BUYER IN
#{st_buyer_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND TO_CHAR(TO_DATE(#{st_to_date},'YYYYMMDD') + 2,'YYYYMMDD')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND ( PODT.PO_NO IN
#{item}
OR PODT.LEGACY_PO_NO IN
#{item}
)
AND POHD.AGENT IN
#{st_agent_code}
AND IVDT.INV_NO = #{st_iv_no}
AND IVDT.INV_NO IN
#{st_iv_no_barcode}
AND EXISTS (SELECT 'X' FROM ICOMIVHD WHERE BUYER = IVDT.BUYER AND INV_NO = IVDT.INV_NO AND STATUS <> 'D' AND PARCEL_INV_NO = #{st_iv_no})
AND POHD.DOC_TYPE = #{st_doc_type}
GROUP BY PODT.BUYER,PODT.PO_NO,IVDT.INV_NO,PODT.DELAY_REMARK ) X WHERE 1=1
AND 1=1
AND X.STATUS = #{st_status_check}
AND 1=0
UNION ALL
SELECT '간선입고예정' AS STATUS, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER)) AS BUYER_NAME, MAX(POHD.PO_CREATE_DATE) AS PO_CREATE_DATE, MAX(PODT.RD_DATE) AS RD_DATE, COUNT(PODT.PO_SEQ) AS PO_CNT, MAX(POHD.DELY_TO_LOCATION) AS DELY_TO_LOCATION, MAX(PRDT.ADD_USER_NAME) AS ADD_USER_NAME, MAX(PRDT.ADD_USER_TEL) AS ADD_USER_TEL, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_NAME, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_TEL_NO, MAX(IVDT.INVOICE_DATE) AS GR_DATE_RE, PODT.PO_NO AS PO_NO, MAX(PODT.LEGACY_PO_NO) AS LEGACY_PO_NO, IVDT.INV_NO AS INV_NO, SUM(PODT.ITEM_AMT) AS ITEM_AMT, MAX(DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반')) AS DOC_TEXT, MAX(POHD.DOC_TYPE) AS DOC_TYPE, MAX(POHD.AGENT) AS AGENT, PODT.BUYER AS BUYER, MAX((SELECT PRE_GR_FLAG FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D')) AS PRE_GR_FLAG, MAX(POHD.PO_REMARK) AS PO_REMARK, PODT.DELAY_REMARK, MAX(PODT.SCM_REMARK) AS SCM_REMARK, MAX(TO_CHAR(TO_DATE(PODT.RD_DATE,'YYYY/MM/DD')-2,'YYYYMMDD')) AS CENTER_SCHD_DATE, ( SELECT NVL(MAX(A.DELY_BUNDLE_FLAG),'N') FROM ICOMPRDT A, ICOMPODT B WHERE A.BUYER = B.BUYER AND A.PR_NO = B.PR_NO AND A.STATUS != 'D' AND B.STATUS != 'D' AND B.BUYER = PODT.BUYER AND B.PO_NO = PODT.PO_NO AND A.DELY_BUNDLE_FLAG = 'Y' ) AS DELY_BUNDLE_FLAG, '' AS DEPT_WAREHOUSE_CODE, MAX(PODT.WAREHOUSE_CODE) AS DEST_WAREHOUSE_CODE, 'Y' AS HUB_YN FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMIVDT IVDT
WHERE 1=1
WHERE 1=0
AND 1=1
AND 1=0
AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' AND NVL(IVDT.WMS_GR_QTY,0) != NVL(IVDT.INV_QTY,0) AND PODT.WAREHOUSE_CODE != #{st_warehouse_code} AND PODT.WAREHOUSE_CODE IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND FLAG = 'Y' AND TEXT7 IS NOT NULL) AND EXISTS (SELECT 'X' FROM SUPLINFO2 WHERE SUPPLIER = POHD.AGENT AND DELY_TO_CENTER = #{st_warehouse_code}) AND NOT EXISTS (SELECT 'X' FROM HUBIVDT WHERE BUYER = IVDT.BUYER AND S_INV_NO = IVDT.INV_NO AND S_INV_SEQ = IVDT.INV_SEQ AND STATUS <> 'D')
AND PODT.BUYER IN
#{st_buyer_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND TO_CHAR(TO_DATE(#{st_to_date},'YYYYMMDD') + 2,'YYYYMMDD')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND ( PODT.PO_NO IN
#{item}
OR PODT.LEGACY_PO_NO IN
#{item}
)
AND POHD.AGENT IN
#{st_agent_code}
AND IVDT.INV_NO = #{st_iv_no}
AND IVDT.INV_NO IN
#{st_iv_no_barcode}
AND EXISTS (SELECT 'X' FROM ICOMIVHD WHERE BUYER = IVDT.BUYER AND INV_NO = IVDT.INV_NO AND STATUS <> 'D' AND PARCEL_INV_NO = #{st_iv_no})
AND POHD.DOC_TYPE = #{st_doc_type}
GROUP BY PODT.PO_NO, PODT.BUYER, IVDT.INV_NO, PODT.DELAY_REMARK ) A, ( SELECT C.CAR_ID, C.CAR_NO, C.CAR_PERSON_NAME, C.CAR_PERSON_TEL, C.BASE_YN, C.BUYER FROM BNTBUYERCARINFO C WHERE C.BASE_YN = 'Y' ) B WHERE 1=1 AND A.BUYER = B.BUYER(+)
ORDER BY A.GR_DATE_RE, A.BUYER_NAME, A.RD_DATE, A.PO_NO
ORDER BY A.BUYER_NAME, A.RD_DATE, A.PO_NO
ORDER BY A.AGENT_NAME, A.RD_DATE, A.PO_NO
ORDER BY A.PO_NO, A.RD_DATE, A.BUYER_NAME
ORDER BY A.INV_NO, A.BUYER_NAME, A.PO_NO
ORDER BY A.RD_DATE, A.GR_DATE_RE, A.BUYER_NAME, A.PO_NO


			SELECT	/*selectMasterWmGrTrGrCreILegacyIvSerialHyosungSAP*/																					
						GET_CSTMR_DEAL_STTMN_NO( A.BUYER, A.PLANT ) AS LEGACY_IV_SERIAL	
  			FROM (	
    				SELECT BUYER, PO_NO, PLANT	
