/*insertMasterWmGrTrGrCreWMSIVDT*/ INSERT INTO WMSIVDT ( WAREHOUSE_CODE, SELLER, INV_NO, INV_SEQ, BUYER, STATUS, SEND_DATE, SEND_TIME, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, CONFIRM_DATE, CONFIRM_TIME, BUYER_ITEM_NO, SELLER_ITEM_NO, STDCATLG_ID, DESCRIPTION, SPECIFICATION, UNIT_MEASURE, PROCESS_TYPE, PO_QTY, GR_QTY, INV_QTY, UNIT_PRICE, LIST_PRICE, UNIT_AMT, LIST_AMT, ORIGIN_CODE, MAKER_NAME, AGENT, PO_NO, PO_SEQ, S_INV_NO, S_INV_SEQ, REF_PR_NO, PR_NO, PR_SEQ, LEGACY_PO_NO, LEGACY_PO_SEQ, DELY_TO_LOCATION, PO_DATE, GR_DATE, INV_DATE, DELIVERY_QTY, DELIVERY_DATE, ADD_USER_ID, CHANGE_USER_ID, DELIVERY_USER_ID, LEGACY_IV_SERIAL, DELIVERY_COMPANY, DELIVERY_NO , CMS_CATLG_ID, DELIVERY_PERSON, SCHEDULED_DATE ,BOX_QTY ,CAR_ID ,CAR_NO ,CAR_PERSON_TEL ,CAR_PERSON_NAME ,TAG_NO
) ( SELECT #{st_warehouse_code} AS WAREHOUSE_CODE, -- [01] WAREHOUSE_CODE IVDT.SELLER AS SELLER, #{orderno} AS INV_NO, -- [02] INV_NO (SELECT TO_CHAR(NVL(TO_NUMBER(MAX(WD.INV_SEQ)),0)+1,'FM000000') FROM WMSIVDT WD WHERE WD.WAREHOUSE_CODE = #{st_warehouse_code} AND WD.INV_NO = #{orderno} )AS INV_SEQ, IVDT.BUYER AS BUYER, 'C' AS STATUS, '' AS SEND_DATE, '' AS SEND_TIME, TO_CHAR(SYSDATE, 'YYYYMMDD') AS ADD_DATE, TO_CHAR(SYSDATE, 'HH24MISS') AS ADD_TIME, TO_CHAR(SYSDATE, 'YYYYMMDD') AS CHANGE_DATE, TO_CHAR(SYSDATE, 'HH24MISS') AS CHANGE_TIME, TO_CHAR(SYSDATE, 'YYYYMMDD') AS CONFIRM_DATE, TO_CHAR(SYSDATE, 'HH24MISS') AS CONFIRM_TIME, IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO, IVDT.SELLER_ITEM_NO AS SELLER_ITEM_NO, PODT.CMS_CATLG_ID AS STDCATLG_ID, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, PODT.UNIT_MEASURE AS UNIT_MEASURE, PODT.PROCESS_TYPE AS PROCESS_TYPE, PODT.ITEM_QTY AS PO_QTY, IVDT.WMS_GR_QTY AS GR_QTY, ${INV_QTY} AS INV_QTY, -- [04] INV_QTY PODT.UNIT_PRICE AS UNIT_PRICE, NVL(PODT.AGENT_PRICE, 0) AS LIST_PRICE, ROUND(${INV_QTY} * NVL(PODT.UNIT_PRICE, 0)) AS UNIT_AMT, -- [05] INV_QTY ROUND(${INV_QTY} * NVL(PODT.AGENT_PRICE, 0)) AS LIST_AMT, -- [06] INV_QTY PODT.ORIGIN_CODE AS ORIGIN_CODE, PODT.MAKER_NAME AS MAKER_NAME, POHD.AGENT AS AGENT, PODT.PO_NO AS PO_NO, PODT.PO_SEQ AS PO_SEQ, IVDT.INV_NO AS S_INV_NO, IVDT.INV_SEQ AS S_INV_SEQ, PODT.REF_PR_NO AS REF_PR_NO, PODT.PR_NO AS PR_NO, PODT.PR_SEQ AS PR_SEQ, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, PODT.DELY_TO_LOCATION AS DELY_TO_LOCATION, POHD.PO_CREATE_DATE AS PO_DATE, IVDT.WMS_GR_DATE AS GR_DATE, #{st_ivk_date} AS INV_DATE, -- [07] INV_DATE 0 AS DELIVERY_QTY, '' AS DELIVERY_DATE, #{st_user_id} AS ADD_USER_ID, -- [08] ADD_USER_ID #{st_user_id} AS CHANGE_USER_ID, -- [09] CHANGE_USER_ID '' AS DELIVERY_USER_ID, #{LEGACY_IV_SERIAL} AS LEGACY_IV_SERIAL, -- [10] LEGACY_IV_SERIAL '' AS DELIVERY_COMPANY, '' AS DELIVERY_NO, PODT.CMS_CATLG_ID AS CMS_CATELG_ID, '' AS DELIVERY_PERSON -- [11] DELIVERY_PERSON ,#{SCHEDULED_DATE} AS SCHEDULED_DATE ,${BOX_QTY} AS BOX_QTY ,#{CAR_ID} AS CAR_ID ,#{CAR_NO} AS CAR_NO ,#{CAR_PERSON_TEL} AS CAR_PERSON_TEL ,#{CAR_PERSON_NAME} AS CAR_PERSON_NAME ,IVDT.TAG_NO AS TAG_NO
FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMIVDT IVDT, ICOMIVHD IVHD WHERE PODT.BUYER = #{BUYER} -- [12] BUYER AND PODT.PO_NO = #{PO_NO} -- [13] PO_NO AND PODT.PO_SEQ = #{PO_SEQ} -- [14] PO_SEQ AND IVDT.INV_NO = #{INV_NO} -- [15] INV_NO AND IVDT.INV_SEQ = #{INV_SEQ} -- [16] INV_SEQ AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.SELLER = IVHD.SELLER AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO = IVHD.INV_NO AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND IVHD.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' )


				/*insertMasterWmGrTrGrCreICOMIVDT*/ 	
        		  UPDATE ICOMIVDT									
        			   SET WMS_IVK_QTY = NVL(WMS_IVK_QTY, 0) + ${INV_QTY}	 
        			         ,SCHEDULED_DATE = #{SCHEDULED_DATE}
        			         ,BOX_QTY = ${BOX_QTY}	
        			         ,CAR_ID = #{CAR_ID}	
        			         ,CAR_NO =#{CAR_NO}
        			         ,CAR_PERSON_TEL= #{CAR_PERSON_TEL}	
        			         ,CAR_PERSON_NAME = #{CAR_PERSON_NAME}
        			 WHERE BUYER = #{BUYER}								 -- 2 BUYER
        			   AND INV_NO = #{INV_NO}								 -- 3 INV_NO
        			   AND INV_SEQ = #{INV_SEQ}								 -- 4 INV_SEQ
        			   AND STATUS <> 'D'							
        			   AND NVL(WMS_IVK_QTY, 0) + ${INV_QTY} <= INV_QTY		 -- 5 INV_QTY

mapper.select:

