UPDATE ICOMPODT
     SET DELAY_REMARK = #{st_DELAY_REMARK}
   WHERE PO_NO = #{st_PO_NO}
       AND BUYER = #{st_BUYER}


/* updateMasterWmGrTrGrCreHubIcomivdt */
UPDATE	ICOMIVDT
SET		HUB_FLAG = #{HUB_FLAG}
WHERE	BUYER = #{BUYER}
AND		INV_NO = #{INV_NO}
AND		PO_NO = #{PO_NO}
AND		STATUS != 'D'
AND		HUB_FLAG IN ('Y', 'C', 'G')


AND		INV_SEQ = #{INV_SEQ}


/* updateMasterWmGrTrGrCreHubIcomivdt_v2 */
UPDATE	ICOMIVDT
SET		HUB_FLAG = #{HUB_FLAG}
		,DELIVERY_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
		,DELIVERY_QTY = NVL(INV_QTY, 0)
WHERE	BUYER = #{BUYER}
AND		INV_NO = #{INV_NO}
AND		PO_NO = #{PO_NO}
